      if (command === 'watch_unsubscribe') return Promise.resolve(true);
      return detailIpc(command, args);
    });
    renderDetail(
      { detail: detail({ id: URL_ID, name: 'add-feature' }), artifacts: PROPOSAL_ENVELOPES },
      ROOT,
      `/changes/${URL_ID}`,
