    expect(
      invokeMock.mock.calls.some(
        ([name, args]) =>
          name === 'read_exec_output_delta' &&
          (args as { execId?: string }).execId === 'exec-mutation-1',
      ),
    ).toBe(true);
  });

  it('异常：miss（未知 exec_id / 记录缺失）→ stdout 空态呈现，不因 id 寻址漂移而炸图', async () => {
