  it('workspace_config reject（含无效 root Err reject）：config-error inline 呈现、无 toast 顶替、壳不崩（AC-7 全链核对）', async () => {
    await restored();

    configReject = 'root 无效（C:\\demo\\alpha）：不存在';
    fireEvent.click(screen.getByTestId('nav-config'));

    await waitFor(() => expect(screen.getByTestId('config-error') !== null).toBe(true));
    expect(screen.getByTestId('config-error').textContent).toContain('解析失败');
    expect(screen.getByTestId('config-error').textContent).toContain('root 无效');
    // inline 持久、无 toast 顶替
    await act(async () => {
      await new Promise((resolve) => setTimeout(resolve, 20));
    });
    expect(screen.getByTestId('config-error') !== null).toBe(true);
    expect(document.querySelector('[data-sonner-toast]')).toBeNull();

    // 壳不崩：可切回变更页
    fireEvent.click(screen.getByTestId('nav-changes'));
    await waitFor(() => expect(screen.getByText('add-feature') !== null).toBe(true));
  });

  it('切换 workspace（sidebar 选择器）后停留 /config：以新根重发 workspace_config、旧根配置不呈现（AC-6 切换重取的壳层核对）', async () => {
    await restored();

    fireEvent.click(screen.getByTestId('nav-config'));
    await waitFor(() =>
      expect(screen.getByTestId('config-view').textContent).toContain(FIRST.root),
    );

    await openWorkspaceMenu();
    fireEvent.click(screen.getByRole('menuitem', { name: SECOND.name }));

    await waitFor(() =>
      expect(invokeMock).toHaveBeenCalledWith('workspace_config', { root: SECOND.root }),
    );
    await waitFor(() =>
      expect(screen.getByTestId('config-view').textContent).toContain(SECOND.root),
    );
    // 旧根配置不呈现、恰以新旧根各重取一次
    expect(screen.getByTestId('config-view').textContent).not.toContain(FIRST.root);
    const configRoots = invokeMock.mock.calls
      .filter(([name]) => name === 'workspace_config')
      .map(([, params]) => (params as { root: string }).root);
    expect(configRoots).toEqual([FIRST.root, SECOND.root]);
  });
});

// ---------------------------------------------------------------------------
// 关系五：构建模式穿透（IPC `app_environment` 单源 → DEV 徽标 / 更新检查判据，
// desktop-build-mode-split AC-14）。徽标解决「两个 app 同跑，我看的是哪个库」：
// `title` 携数据根；prod 构建与环境未就绪（null）不渲染。版本号不加 `-dev`
// 后缀（不动版本语义，免污染 tag 与 updater 比较）。
// ---------------------------------------------------------------------------

describe('App：构建模式穿透（mode → DEV 徽标 / 更新检查判据）', () => {
  beforeEach(() => {
    window.location.hash = '';
    getVersionMock.mockReset();
    invokeMock.mockReset();
    openMock.mockReset();
    checkMock.mockReset();
    checkMock.mockResolvedValue(null);
    getVersionMock.mockResolvedValue('0.1.0');
    toast.dismiss();
    mockIpc();
  });

  it('挂载期新增恰一次 app_environment（不随视图切换 / 刷新重发）', async () => {
    await restored();

    expect(countOf('app_environment')).toBe(1);
    fireEvent.click(screen.getByRole('button', { name: '刷新' }));
    await waitFor(() =>
      expect(invokeMock.mock.calls.filter(([name]) => name === 'list_changes').length).toBe(2),
    );
    expect(countOf('app_environment')).toBe(1);
  });

  it("mode='dev' 呈 DEV 徽标：文本 DEV 且 title 逐字等于数据根", async () => {
    await restored();

    const badge = screen.getByTestId('dev-badge');
    expect(badge.textContent).toBe('DEV');
    expect(badge.getAttribute('title')).toBe(DEV_DATA_ROOT);
  });

  it("mode='prod' 无徽标且更新指示链路照常（check 一次、无新版本不渲染按钮）", async () => {
    environmentMode = 'prod';
    await restored();

    await waitFor(() => expect(checkMock).toHaveBeenCalledTimes(1));
    expect(screen.queryByTestId('dev-badge')).toBeNull();
    expect(screen.queryByRole('button', { name: /更新到/ })).toBeNull();
    expect(screen.getByText('v0.1.0') !== null).toBe(true);
  });

  it('mode 未就绪 / IPC 失败静默：三形态均无徽标、无错误态、其余取数不受阻', async () => {
    for (const mode of ['reject', 'pending', 'null'] as const) {
      invokeMock.mockReset();
      mockIpc();
      environmentMode = mode;
      cleanup();
      window.location.hash = '';
      toast.dismiss();

      render(<App />);
      await waitFor(() =>
        expect(invokeMock).toHaveBeenCalledWith('list_changes', { root: FIRST.root }),
      );
      await waitFor(() => expect(screen.getByText('add-feature') !== null).toBe(true));

      expect(screen.queryByTestId('dev-badge')).toBeNull();
      expect(document.querySelector('[data-sonner-toast]')).toBeNull();
      expect(checkMock).not.toHaveBeenCalled();
      cleanup();
    }
  });

  it('载荷不合法不污染壳态：非法枚举值 + 类型错 → 无徽标、更新检查零调用', async () => {
    environmentMode = 'invalid';
    await restored();

    expect(screen.queryByTestId('dev-badge')).toBeNull();
    expect(checkMock).not.toHaveBeenCalled();
    expect(screen.getByText('add-feature') !== null).toBe(true);
  });

  it("mode='dev' 透传到 updater：check 零调用、版本号照拉且无 -dev 后缀", async () => {
    await restored();

    await waitFor(() => expect(getVersionMock).toHaveBeenCalledTimes(1));
    expect(checkMock).not.toHaveBeenCalled();
    const header = document.querySelector('header');
    expect(header !== null).toBe(true);
    expect(within(header!).getByText('v0.1.0') !== null).toBe(true);
    expect(within(header!).queryByText(/v0\.1\.0-dev/)).toBeNull();
  });

  it("mode='prod' 透传到 updater：发现新版本时渲染「更新到 vX」入口", async () => {
    environmentMode = 'prod';
    checkMock.mockResolvedValue(fakeUpdate('0.2.0'));
    render(<App />);

    await waitFor(() =>
      expect(screen.getByRole('button', { name: '更新到 v0.2.0' }) !== null).toBe(true),
    );
    expect(screen.queryByTestId('dev-badge')).toBeNull();
  });

  it('既有序列断言 filter 口径：过滤 app_environment 后与既有期望序列相等', async () => {
    await restored();

    // 恢复为纯查询链（挂载取数 → 以默认序第一名取 change 列表）
    expect(commandsExceptEnvironment()).toEqual(['list_workspaces', 'list_changes']);
    // 「只有 list_workspaces」口径同样先 filter：空清单启动时过滤后无其它命令
    cleanup();
    invokeMock.mockReset();
    mockIpc();
    remaining = [];
    window.location.hash = '';
    render(<App />);
    await waitFor(() => expect(screen.getByText('添加新文件夹') !== null).toBe(true));
    await act(async () => {
      await new Promise((resolve) => setTimeout(resolve, 10));
    });
    expect(commandsExceptEnvironment().every((name) => name === 'list_workspaces')).toBe(true);
    // 环境取数次数单列断言（与序列断言解耦）
    expect(countOf('app_environment')).toBe(1);
  });

  it('欢迎屏（空清单）无徽标：ShellHeader 仅在选中 workspace 后渲染', async () => {
    remaining = [];
    render(<App />);

    await waitFor(() => expect(screen.getByText('添加新文件夹') !== null).toBe(true));
    expect(screen.queryByTestId('dev-badge')).toBeNull();
    expect(countOf('app_environment')).toBe(1);
  });
});

// ---------------------------------------------------------------------------
// archi 章节：/architecture 路由（挂载点 A）与侧栏入口跳转
// ---------------------------------------------------------------------------

describe('App：架构页路由（/architecture）', () => {
  beforeEach(() => {
    window.location.hash = '';
    getVersionMock.mockReset();
    invokeMock.mockReset();
    openMock.mockReset();
    checkMock.mockReset();
    checkMock.mockResolvedValue(null);
    getVersionMock.mockResolvedValue('0.1.0');
    toast.dismiss();
    mockIpc();
  });

  it('应在 hash 落 #/architecture 时渲染架构页并激活 nav-architecture', async () => {
    window.location.hash = '#/architecture';
    render(<App />);

    await waitFor(() => expect(screen.getByTestId('archi-refresh') !== null).toBe(true));
    await waitFor(() => expect(screen.getByTestId('archi-canvas') !== null).toBe(true));
    expect(screen.getByTestId('nav-architecture').hasAttribute('data-active')).toBe(true);
    expect(screen.getByTestId('nav-changes').hasAttribute('data-active')).toBe(false);
    expect(screen.queryByText('add-feature')).toBeNull();
    // 取数只发 archi_graph（携当前根）
    expect(invokeMock).toHaveBeenCalledWith('archi_graph', { root: FIRST.root });
  });

  it('应从侧栏进入架构页并在切回变更页时复原（分支卸载 / 挂载）', async () => {
    await restored();
    expect(screen.getByText('add-feature') !== null).toBe(true);

    fireEvent.click(screen.getByTestId('nav-architecture'));
    await waitFor(() => expect(screen.getByTestId('archi-canvas') !== null).toBe(true));
    expect(window.location.hash).toBe('#/architecture');
    expect(screen.queryByText('add-feature')).toBeNull();

    fireEvent.click(screen.getByTestId('nav-changes'));
    await waitFor(() => expect(screen.getByText('add-feature') !== null).toBe(true));
    expect(window.location.hash).toBe('#/changes');
    expect(screen.queryByTestId('archi-canvas')).toBeNull();
  });

  it('应在 archi_graph reject 时停在 #/architecture 并呈现错误态（不白屏不重定向）', async () => {
    archiReject = 'root 无效（C:）';
    window.location.hash = '#/architecture';
    render(<App />);

    await waitFor(() => expect(screen.getByTestId('archi-canvas-error') !== null).toBe(true));
    expect(screen.getByTestId('archi-canvas-error').textContent).toContain('root 无效');
    expect(window.location.hash).toBe('#/architecture');
    expect(screen.getByTestId('nav-architecture').hasAttribute('data-active')).toBe(true);

    // 切走再切回仍可用（错误不污染路由）
    fireEvent.click(screen.getByTestId('nav-changes'));
    await waitFor(() => expect(screen.getByText('add-feature') !== null).toBe(true));
    expect(window.location.hash).toBe('#/changes');
  });

  it('应在切走再切回时重发 archi_graph（挂载触发，不做跨挂载缓存）', async () => {
    window.location.hash = '#/architecture';
    render(<App />);
    await waitFor(() => expect(countOf('archi_graph')).toBe(1));

    fireEvent.click(screen.getByTestId('nav-changes'));
    await waitFor(() => expect(screen.getByText('add-feature') !== null).toBe(true));

    fireEvent.click(screen.getByTestId('nav-architecture'));
    await waitFor(() => expect(countOf('archi_graph')).toBe(2));
  });

  it('收起态下新增架构 Agent 面板不引入会话取数（invoke 序列按 filter 口径稳定）', async () => {
    window.location.hash = '#/architecture';
    render(<App />);

    await waitFor(() => expect(screen.getByTestId('archi-chat-rail') !== null).toBe(true));
    expect(
      commandsExceptEnvironment().filter((name) =>
        [
          'list_archi_chat_sessions',
          'session_detail',
          'agent_session_transcript',
          'agent_session_watch',
          'agent_start',
        ].includes(name),
      ),
      '收起态零会话取数（新增面板不改变壳层 invoke 序列）',
    ).toEqual([]);
    expect(countOf('archi_graph')).toBe(1);
    expect(countOf('archi_set_gate')).toBe(0);
  });
});

