import { act, fireEvent, render, screen, waitFor, within } from '@testing-library/react';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vite-plus/test';

import type { AskAnswerActions } from '@/components/agent';

import type {
  AgentEvent,
  ArtifactEnvelope,
  ChangeDetail,
