describe('AgentRunHistory：configSnapshot fixture 携 agentInstanceId 键（AC-7 随动）', () => {
  it('补键后清单呈现既有断言保绿（多元素清单 + 两形态快照同口径）', () => {
    const legacy = session('ses-3-1727000000000', 'completed', TS + 3);
    legacy.row.configSnapshot = {
